def section_for_today(content):
    pieces = [piece.strip() for piece in str(content).replace('|', '\n').replace(';', '\n').splitlines() if piece.strip()]
    today_aliases = weekday_aliases[weekday_name] + ['today']
    anchors = []
    for index, piece in enumerate(pieces):
        tokens = word_tokens(piece)
        low = piece.lower()
        if any(alias in tokens for alias in today_aliases) or any(marker and marker in low for marker in date_markers):
            anchors.append(index)
    if not anchors:
        return '\n'.join(pieces)
    sections = []
    for index in anchors:
        first_line = pieces[index]
        low = first_line.lower()
        starts = [low.find(alias) for alias in today_aliases if low.find(alias) >= 0]
        if starts:
            start = min(starts)
            later_other_days = []
            for other_day, aliases in weekday_aliases.items():
                if other_day != weekday_name:
                    later_other_days.extend(position for alias in aliases for position in [low.find(alias, start + 1)] if position >= 0)
            if later_other_days:
                first_line = first_line[start:min(later_other_days)]
        segment = [first_line]
        cursor = index + 1
        while cursor < len(pieces):
            candidate = pieces[cursor]
            candidate_tokens = word_tokens(candidate)
            other_day = any(alias in candidate_tokens for name, aliases in weekday_aliases.items() if name != weekday_name for alias in aliases)
            candidate_numbers = digit_runs(candidate)
            candidate_low = candidate.lower()
            other_date_heading = (len(candidate) < 40 and ((any(value >= 1000 for value in candidate_numbers) and ('-' in candidate or '/' in candidate)) or (any(name in candidate_low for name in month_map) and bool(candidate_numbers))))
            if other_day or other_date_heading:
                break
            segment.append(candidate)
            cursor += 1
        sections.append('\n'.join(segment))
    return '\n'.join(sections)

small_numbers = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14, 'fifteen': 15, 'sixteen': 16, 'seventeen': 17, 'eighteen': 18, 'nineteen': 19, 'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50, 'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90, 'couple': 2}
