def parse_simple_number(tokens):
    numeric = []
    for token in tokens:
        try:
            numeric.append(float(token))
        except ValueError:
            pass
    if numeric:
        return max(numeric)
    current = 0
    seen = False
    for token in tokens:
        if token in ('a', 'an'):
            current += 1
            seen = True
        elif token in small_numbers:
            current += small_numbers[token]
            seen = True
        elif token == 'hundred':
            current = max(current, 1) * 100
            seen = True
    return float(current) if seen else None

def quantity_before(tokens, unit_index):
    start = unit_index - 1
    while start >= 0:
        token = tokens[start]
        try:
            float(token)
            allowed = True
        except ValueError:
            allowed = token in quantity_words
        if not allowed:
            break
        start -= 1
    phrase = tokens[start + 1:unit_index]
    if not phrase:
        return None
    fraction = 0.5 if 'half' in phrase else (0.25 if 'quarter' in phrase else 0.0)
    if fraction:
        fraction_index = phrase.index('half') if 'half' in phrase else phrase.index('quarter')
        base_tokens = [token for token in phrase[:fraction_index] if token not in ('and', 'a', 'an', 'of')]
        base = parse_simple_number(base_tokens) or 0.0
        return base + fraction
    return parse_simple_number([token for token in phrase if token not in ('and', 'of')])

def expression_tokens(text):
    raw = ''.join(ch.lower() if (ch.isalnum() or ch in '.:') else ' ' for ch in str(text)).split()
    expanded = []
    for token in raw:
        split_at = 0
        while split_at < len(token) and (token[split_at].isdigit() or token[split_at] == '.'):
            split_at += 1
        if 0 < split_at < len(token) and token[split_at:].isalpha():
            expanded.extend([token[:split_at], token[split_at:]])
        else:
            expanded.append(token)
    return expanded, raw

def clock_points(raw_tokens):
    points = []
    for index, raw_token in enumerate(raw_tokens):
        token = raw_token
        meridiem = None
        if token.endswith('am') or token.endswith('pm'):
            meridiem = token[-2:]
            token = token[:-2]
        elif index + 1 < len(raw_tokens) and raw_tokens[index + 1] in ('am', 'pm'):
            meridiem = raw_tokens[index + 1]
        parts = token.split(':')
        is_clock = len(parts) == 2 and all(part.isdigit() for part in parts)
        if not is_clock and meridiem is not None and token.isdigit():
            parts = [token, '0']
            is_clock = True
        if is_clock:
            hour, minute = int(parts[0]), int(parts[1])
            if 0 <= minute < 60 and 0 <= hour <= 23:
                if meridiem == 'am':
                    hour = hour % 12
                elif meridiem == 'pm':
                    hour = hour % 12 + 12
                points.append(hour * 60 + minute)
    return points

duration_units = {'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600, 'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60, 's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1}
