def line_requirements(line):
    tokens, raw = expression_tokens(line)
    duration_seconds = 0.0
    song_counts = []
    for index, token in enumerate(tokens):
        if token in duration_units:
            quantity = quantity_before(tokens, index)
            if quantity is not None:
                duration_seconds += quantity * duration_units[token]
        if token in song_units:
            quantity = quantity_before(tokens, index)
            if quantity is not None:
                song_counts.append(int(quantity))
    points = clock_points(raw)
    if duration_seconds == 0 and len(points) >= 2:
        delta = (points[-1] - points[0]) % 1440
        if delta > 720:
            alternate = (points[-1] + 720 - points[0]) % 1440
            if 0 < alternate <= 720:
                delta = alternate
        duration_seconds = delta * 60
    if duration_seconds == 0 and 'duration' in line.lower():
        colon_values = [token for token in raw if token.count(':') in (1, 2) and all(part.isdigit() for part in token.split(':'))]
        if len(colon_values) == 1:
            parts = [int(part) for part in colon_values[0].split(':')]
            if len(parts) == 3:
                duration_seconds = parts[0] * 3600 + parts[1] * 60 + parts[2]
            elif parts[0] > 12:
                duration_seconds = parts[0] * 60 + parts[1]
            else:
                duration_seconds = parts[0] * 3600 + parts[1] * 60
    return duration_seconds, song_counts, points

def extract_requirements(section):
    duration_rows = []
    song_counts = []
    loose_clock_points = []
    for line in section.splitlines():
        seconds, counts, points = line_requirements(line)
        if seconds > 0:
            duration_rows.append((line.lower(), seconds))
        else:
            loose_clock_points.extend(points)
        song_counts.extend(counts)
    summary_rows = [seconds for line, seconds in duration_rows if any(marker in line for marker in ('total', 'overall', 'workout duration', 'workout lasts', 'length of workout'))]
    duration_seconds = max(summary_rows) if summary_rows else sum(seconds for _, seconds in duration_rows)
    if duration_seconds == 0 and len(loose_clock_points) >= 2:
        delta = (loose_clock_points[-1] - loose_clock_points[0]) % 1440
        if delta > 720:
            alternate = (loose_clock_points[-1] + 720 - loose_clock_points[0]) % 1440
            if 0 < alternate <= 720:
                delta = alternate
        duration_seconds = delta * 60
    return int(duration_seconds), (max(song_counts) if song_counts else 0)

